import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const prismaDir = path.join(__dirname, '..', 'prisma');
const aquasphereFile = path.join(prismaDir, 'aquasphere-models.prisma');
const badanaFile = path.join(prismaDir, 'badana-models.prisma');
const outputFile = path.join(prismaDir, 'schema.prisma');

const header = `// =========================================================================
// THIS FILE IS AUTO-GENERATED BY scripts/generate-schema.js
// DO NOT EDIT DIRECTLY.
// Edit aquasphere-models.prisma and badana-models.prisma, then run \`npm run db:generate-schema\`
// =========================================================================

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  schemas  = ["auth", "aquasphere", "badana"]
}

// ==========================================
// AUTH SCHEMA
// ==========================================

model User {
  id           String   @id @default(uuid())
  email        String   @unique
  passwordHash String
  role         Role
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@schema("auth")
}

enum Role {
  OWNER
  ADMIN
  PRODUCTION_MANAGER
  ACCOUNTANT
  MARKETING_MANAGER

  @@schema("auth")
}
`;

function generateSchema() {
  const aquasphereContent = fs.readFileSync(aquasphereFile, 'utf8');
  const badanaContent = fs.readFileSync(badanaFile, 'utf8');

  const fullSchema = [
    header,
    '// ==========================================\n// AQUASPHERE SCHEMA\n// ==========================================\n',
    aquasphereContent,
    '\n// ==========================================\n// BADANA SCHEMA\n// ==========================================\n',
    badanaContent
  ].join('\n');

  fs.writeFileSync(outputFile, fullSchema, 'utf8');
  console.log('Successfully generated prisma/schema.prisma');
}

generateSchema();
